ALTER POLICY metrics_read ON public.indicadores_metrics USING(public.indicadores_role(auth.uid()) IS NOT NULL AND (objective_id IS NULL OR public.indicadores_objective_visible(objective_id)));
ALTER POLICY metrics_update ON public.indicadores_metrics USING(public.indicadores_role(auth.uid()) IN ('admin','editor') AND (objective_id IS NULL OR public.indicadores_objective_visible(objective_id))) WITH CHECK(public.indicadores_role(auth.uid()) IN ('admin','editor') AND (objective_id IS NULL OR public.indicadores_objective_visible(objective_id)));
ALTER POLICY objectives_read ON public.indicadores_objectives USING(public.indicadores_role(auth.uid()) IS NOT NULL AND (public.indicadores_role(auth.uid())='admin' OR (NOT confidential OR auth.uid()=ANY(allowed_user_ids))) AND (parent_id IS NULL OR public.indicadores_objective_visible(parent_id)));